# Map each input cell to its output cell
# For each color, sort input cells by (row, col) and output cells by (row, col)
# Then map i-th input to i-th output for same color

def map_cells(input_grid, output_grid):
    rows_in, cols_in = len(input_grid), len(input_grid[0])
    rows_out, cols_out = len(output_grid), len(output_grid[0])

    input_pos = {}
    for r in range(rows_in):
        for c in range(cols_in):
            if input_grid[r][c] != 0:
                input_pos[(r,c)] = input_grid[r][c]

    output_pos = {}
    for r in range(rows_out):
        for c in range(cols_out):
            if output_grid[r][c] != 0:
                output_pos[(r,c)] = output_grid[r][c]

    mappings = {}
    for color in sorted(set(list(input_pos.values()) + list(output_pos.values()))):
        inp = sorted([(r,c) for (r,c),col in input_pos.items() if col == color])
        outp = sorted([(r,c) for (r,c),col in output_pos.items() if col == color])

        for (ir, ic), (or_, oc) in zip(inp, outp):
            delta_r = or_ - ir
            delta_c = oc - ic
            key = f"color_{color}_pos_{ic}"
            mappings[key] = (delta_r, delta_c)

    return mappings

