def get_cell_mapping(input_grid, output_grid):
    """Map each input cell (by sorted position) to output cell."""
    rows_in, cols_in = len(input_grid), len(input_grid[0])
    rows_out, cols_out = len(output_grid), len(output_grid[0])

    # Group cells by color
    for grid in [input_grid, output_grid]:
        pass

    mappings = {}  # color -> list of (r,c) tuples
    for grid_name, grid in [("in", input_grid), ("out", output_grid)]:
        mappings[grid_name] = {c: [] for c in range(9+1)}  # colors 0-9

    for r in range(rows_in):
        for c in range(cols_in):
            if input_grid[r][c] != 0:
                color = input_grid[r][c]
                mappings["in"][color].append((r, c))

    for r in range(rows_out):
        for c in range(cols_out):
            if output_grid[r][c] != 0:
                color = output_grid[r][c]
                mappings["out"][color].append((r, c))

    # Map each input cell to output cell (by index in sorted order)
    cell_to_output = {}
    for color in range(1, 10):  # skip 0 (background)
        inp_cells = sorted(mappings["in"].get(color, []))
        outp_cells = sorted(mappings["out"].get(color, []))

        print(f"Color {color}: {len(inp_cells)} input cells → {len(outp_cells)} output cells")

        for (ir, ic), (or_, oc) in zip(inp_cells, outp_cells):
            delta_r, delta_c = or_ - ir, oc - ic
            cell_to_output[(ir, ic)] = (or_, oc)
            print(f"  ({ir},{ic}) → ({or_},{oc}): Δ({delta_r}, {delta_c})")

    return cell_to_output

